/// `tt.trans`: rearrange the dimensions of a tensor
///
/// For example, given a tensor x with shape [1,2,4], transpose(x) with
/// order=[2,0,1] rearranges the tensor to have shape [4,1,2].
///
/// Although this op is called "trans", it implements both tl.trans() and
/// tl.permute().  ("permute" might be a better name, but it's called "trans"
/// because originally it only supported 2D tensors.)
///
/// ## Implementation note on encodings:
///
/// In the TritonGPU dialect (and probably others), an encoding is chosen for
/// this op's output so it's a nop from the perspective of code generation.
///
/// For example, suppose tensor x has an encoding such that GPU thread [i,j,k]
/// has a register containing element [i,j,k] of the tensor.  Now we transpose
/// x with order [2,1,0], i.e. we reverse the order of its dimensions.  In
/// TritonGPU, we will choose a layout for the output of the transpose so that
/// GPU thread [i,j,k] has element [k,j,i] of transpose(x).  But this is the
/// same element it had before!  All we've done is "rename" the element that
/// thread [i,j,k] has.
///
/// The "real" transpose -- i.e. moving data between GPU threads -- occurs in
/// convertLayout ops that appear before and/or after the operation.
///
/// We do this so that you can chain multiple data-movement ops (e.g.
/// transpose+reshape+concat) without going to shared memory after each one.
#[mlir::op("tt.trans", format = "$src attr-dict `:` type($src) `->` type($result)", results(result))]
pub struct TransOp<'a> {
    #[slot(src_ty)]
    pub src: Value<'a>,
    #[attr(dense = "i32")]
    pub order: Attribute<'a>,
    pub src_ty: Type<'a>,
    pub result: Type<'a>,
}

/// `tt.unsplat`: convert a tensor with a single element to a scalar
///
/// Generic form only (result type `result` inferred in C++).
#[mlir::op("tt.unsplat", results(result))]
pub struct UnsplatOp<'a> {
    #[slot(src_ty)]
    pub src: Value<'a>,
    pub src_ty: Type<'a>,
    pub result: Type<'a>,
}

/// The `tt` dialect.
#[mlir::dialect(
    "tt",
    ops = [CallOp, FuncOp, ReturnOp, AddPtrOp, AdvanceOp, AssertOp, AtomicCASOp, AtomicRMWOp, BitcastOp, BroadcastOp, CatOp, ClampFOp, DescriptorGatherOp, DescriptorLoadOp, DescriptorReduceOp, DescriptorScatterOp, DescriptorStoreOp, DotOp, DotScaledOp, ElementwiseInlineAsmOp, ExpandDimsOp, ExternElementwiseOp, FpToFpOp, GatherOp, GetNumProgramsOp, GetProgramIdOp, HistogramOp, IntToPtrOp, JoinOp, LoadOp, MakeRangeOp, MakeTensorDescOp, MakeTensorPtrOp, MapElementwiseOp, MapElementwiseReturnOp, MulhiUIOp, PreciseDivFOp, PreciseSqrtOp, PrintOp, PtrToIntOp, ReduceOp, ReduceReturnOp, ReshapeOp, ScanOp, ScanReturnOp, SplatOp, SplitOp, StoreOp, TransOp, UnsplatOp],
    dependents = ["arith", "math", "scf", "cf", "ub"],
    materializer
)]
pub struct TtDialect;
